def transform(grid):
    from collections import Counter
    h, w = len(grid), len(grid[0])
    counts = Counter(x for row in grid for x in row)
    bg = counts.most_common(1)[0][0]
    color = max((x for x in counts if x != bg), key=counts.get)
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
    r0, r1 = min(r for r, c in points), max(r for r, c in points)
    c0, c1 = min(c for r, c in points), max(c for r, c in points)
    out = [row[:] for row in grid]
    def mark(r, c):
        if out[r][c] == bg:
            out[r][c] = 2
    for c in range(c0, c1 + 1):
        mark(r0, c); mark(r1, c)
    for r in range(r0, r1 + 1):
        mark(r, c0); mark(r, c1)
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] == color]
        if len(cols) >= 4:
            for c in range(min(cols), max(cols) + 1): mark(r, c)
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == color]
        if len(rows) >= 3:
            for r in range(min(rows), max(rows) + 1): mark(r, c)
    return out
